<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>@yield('title', 'School Manager')</title>
    <style>
        *{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#172033;background:#f7f9fc;line-height:1.6}a{color:inherit}.nav{background:#fff;border-bottom:1px solid #e8edf5;display:flex;align-items:center;justify-content:space-between;padding:16px 6%;position:sticky;top:0;z-index:10}.brand{font-weight:800;font-size:20px;text-decoration:none}.navlinks{display:flex;gap:22px;align-items:center}.navlinks a{text-decoration:none;color:#526078;font-weight:600}.navlinks a:hover{color:#1769e0}.btn{display:inline-block;padding:11px 18px;border-radius:9px;text-decoration:none;font-weight:700;border:0;cursor:pointer;background:#1769e0;color:#fff}.btn.secondary{background:#edf3ff;color:#1769e0}.container{width:min(1120px,88%);margin:auto}.hero{padding:90px 0;background:linear-gradient(135deg,#edf4ff,#fff)}.hero h1{font-size:clamp(38px,6vw,64px);line-height:1.05;margin:0 0 20px;max-width:800px}.hero p{font-size:19px;color:#5b667a;max-width:720px}.section{padding:65px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:22px}.card{background:#fff;border:1px solid #e8edf5;border-radius:16px;padding:26px;box-shadow:0 8px 28px rgba(28,47,78,.05)}.card h3{margin-top:0}.muted{color:#68758a}.form-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.field{display:flex;flex-direction:column;gap:7px}.field.full{grid-column:1/-1}.field label{font-weight:700}.field input,.field select,.field textarea{width:100%;padding:12px 13px;border:1px solid #d8e0ec;border-radius:9px;background:#fff;font:inherit}.field textarea{min-height:120px;resize:vertical}.alert{padding:14px 16px;border-radius:10px;margin-bottom:18px}.success{background:#e9f8ef;color:#176b3a}.error{background:#fff0f0;color:#a51d2d}.errors{margin:0 0 18px;padding:14px 18px;background:#fff0f0;color:#a51d2d;border-radius:10px}.footer{background:#172033;color:#dce4f0;padding:40px 0;margin-top:50px}.footer-grid{display:grid;grid-template-columns:2fr 1fr 1fr;gap:30px}.admin-shell{min-height:100vh;background:#f5f7fb}.admin-top{background:#172033;color:#fff;padding:18px 4%;display:flex;justify-content:space-between;align-items:center}.admin-layout{display:grid;grid-template-columns:230px 1fr;min-height:calc(100vh - 66px)}.sidebar{background:#fff;border-right:1px solid #e4e9f2;padding:24px 15px}.sidebar a{display:block;padding:11px 13px;border-radius:8px;text-decoration:none;color:#526078;margin-bottom:5px}.sidebar a.active,.sidebar a:hover{background:#edf3ff;color:#1769e0}.admin-main{padding:30px 4%}.stat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.stat{background:#fff;border:1px solid #e4e9f2;border-radius:14px;padding:22px}.stat strong{font-size:30px;display:block}.table-wrap{overflow:auto;background:#fff;border:1px solid #e4e9f2;border-radius:14px}.table{width:100%;border-collapse:collapse}.table th,.table td{text-align:left;padding:13px 15px;border-bottom:1px solid #edf0f5}.table th{background:#f8f9fc;font-size:13px;text-transform:uppercase;letter-spacing:.03em}@media(max-width:760px){.nav{padding:14px 5%}.navlinks{gap:10px;font-size:13px;flex-wrap:wrap}.form-grid,.footer-grid,.admin-layout{grid-template-columns:1fr}.sidebar{border-right:0;border-bottom:1px solid #e4e9f2}.stat-grid{grid-template-columns:repeat(2,1fr)}.hero{padding:60px 0}.section{padding:45px 0}}
    </style>
</head>
<body>
@yield('body')
</body>
</html>
